templates.css:
body {
  margin: 0;
  padding: 24px 12px;
  background: #e8dccf;
  color: #1f2a1f;
  font: 15px/1.6 Arial,Tahoma,sans-serif;
}
.email {
  max-width: 680px;
  margin: auto;
  background: #faf8f5;
  border-radius: 16px;
  overflow: hidden;
  border: 1px solid #d9cfc2;
}
header {
  padding: 28px;
  text-align: center;
  background: #eef0e9;
}
header img {
  display: block;
  margin: auto;
  object-fit: contain;
}
.brand {
  font: 700 25px/1.3 Georgia,serif;
  margin: 8px 0;
  color: #1f2a1f;
}
header p,
footer p {
  font-size: 12px;
}
section {
  padding: 28px;
}
.eyebrow {
  color: #6b7d5e;
  font-size: 11px;
  font-weight: bold;
  letter-spacing: 2px;
}
h1 {
  font: 400 29px/1.25 Georgia,Tahoma,serif;
  margin: 12px 0;
}
h2 {
  font-size: 16px;
  margin-top: 24px;
}
.reference {
  padding: 16px;
  background: #f0ebe3;
  border-inline-start: 3px solid #718369;
  border-radius: 8px;
}
table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}
th,
td {
  text-align: start;
  vertical-align: top;
  padding: 10px 5px;
  overflow-wrap: anywhere;
  border-bottom: 1px solid #e8dccf;
}
th {
  font-size: 11px;
  color: #526348;
}
.items th:first-child {
  width: 43%;
}
.items td {
  font-size: 12px;
}
.muted {
  color: #676b60;
  white-space: pre-line;
}
.badge {
  color: #526348;
  font-size: 11px;
}
.totals {
  margin-top: 20px;
  background: #f0ebe3;
  border-radius: 8px;
}
.totals td:last-child,
.details td:last-child {
  text-align: end;
}
.grand-total {
  font-weight: bold;
  font-size: 19px;
  color: #304a2c;
}
.details {
  font-size: 13px;
}
.details td {
  white-space: pre-line;
}
.action {
  margin: 24px 0;
}
.action a {
  display: inline-block;
  background: #6b7d5e;
  color: #fff!important;
  padding: 12px 22px;
  border-radius: 8px;
  text-decoration: none;
  font-weight: bold;
}
.notice {
  font-size: 12px;
  color: #676b60;
}
.divider {
  height: 1px;
  background: #d9cfc2;
  margin: 0 28px;
}
footer {
  text-align: center;
  padding: 24px;
  background: #1f2a1f;
  color: #faf8f5;
}
footer a {
  color: #e8dccf;
}
.preheader {
  display: none!important;
  max-height: 0;
  overflow: hidden;
  opacity: 0;
}
@media (max-width:480px) {
  body {
    padding: 8px;
  }
  section {
    padding: 18px;
  }
  h1 {
    font-size: 24px;
  }
  .items th,
  .items td {
    font-size: 11px;
    padding: 8px 3px;
  }
  .grand-total {
    font-size: 17px;
  }
}
